    assert d[:4]==b'\x7fELF', path
    e_phoff=struct.unpack_from('<I',d,28)[0]
    e_phentsize=struct.unpack_from('<H',d,42)[0]
    e_phnum=struct.unpack_from('<H',d,44)[0]
    loads=[]
    for i in range(e_phnum):
        o=e_phoff+i*e_phentsize
        p_type=struct.unpack_from('<I',d,o)[0]
        p_offset=struct.unpack_from('<I',d,o+4)[0]
        p_vaddr=struct.unpack_from('<I',d,o+8)[0]
        p_filesz=struct.unpack_from('<I',d,o+16)[0]
        loads.append((p_type,p_offset,p_vaddr,p_filesz))
    # find PT_DYNAMIC (2) and PT_LOAD
    dyn=None
    loadsz=None
    for t,off,va,sz in loads:
        if t==2: dyn=(off,va,sz)
        if t==1: loadsz=(va,sz)
