    def v2o(v):
        for t,o,va2,sz2 in loads:
            if t==1 and va2<=v<va2+sz2:
                return o+(v-va2)
        return None
    entries=[]
    for i in range(sz//8):
        tag,val=struct.unpack_from('<iI',d,off+i*8)
        if tag==0: break
        entries.append((tag,val))
    strtab=None; needed=[]; soname=None
