#!/usr/bin/env python3
"""Neutralise NULL entries in DT_INIT_ARRAY / DT_FINI_ARRAY.

Android's bionic linker skips NULL entries in the init/fini arrays
(soinfo::call_init does `if (init_function == NULL) continue;`), but glibc's
ld.so calls every entry unconditionally:

    glibc/elf/dl-init.c
        for (i = 0; i < n; ++i)
          call_init_func (array[i], ...);      // no NULL check

The APK's libmain.so ships a .init_array holding one NULL pointer, so on the
R36S ld.so jumps to address 0 and the process dies with SIGSEGV before
JNI_OnLoad is ever reached.

This script removes those entries:
  * trailing NULLs -> DT_INIT_ARRAYSZ is simply shortened
  * interior NULLs -> the remaining entries are shifted down one slot and
                      the matching R_ARM_RELATIVE r_offsets are fixed up
"""
import struct
import sys
import shutil

R_ARM_RELATIVE = 23

def phdrs(d):
    e_phoff = struct.unpack_from('<I', d, 28)[0]
    e_phentsize = struct.unpack_from('<H', d, 42)[0]
    e_phnum = struct.unpack_from('<H', d, 44)[0]
    segs = []
    for i in range(e_phnum):
        o = e_phoff + i * e_phentsize
        t, off, va, pa, fsz, msz, fl, al = struct.unpack_from('<8I', d, o)
        segs.append([t, off, va, fsz, msz])
    return segs

def v2o(segs, v):
    for t, off, va, fsz, msz in segs:
        if t == 1 and va <= v < va + msz:
            return off + (v - va)
    return None

def dynamic(d, segs):
    dyn = [s for s in segs if s[0] == 2][0]
    off = dyn[1]
    ents = []
    for i in range(dyn[3] // 8):
        tag, val = struct.unpack_from('<iI', d, off + i * 8)
        ents.append([tag, val, off + i * 8])
        if tag == 0:
            break
    return ents

def set_tag(ents, tag, value):
    for e in ents:
        if e[0] == tag:
            e[1] = value
            return True
    return False

def reloc_table(d, segs, ents):
    m = {e[0]: e[1] for e in ents}
    if 17 not in m or 18 not in m:
        return None, {}
    ro = v2o(segs, m[17])
    if ro is None:
        return None, {}
    idx = {}
    for i in range(m[18] // 8):
        off, info = struct.unpack_from('<II', d, ro + i * 8)
        if (info & 0xff) == R_ARM_RELATIVE:
            idx[off] = ro + i * 8
    return ro, idx

def patch(path, dry=False):
    d = bytearray(open(path, 'rb').read())
    segs = phdrs(d)
    ents = dynamic(d, segs)
    m = {e[0]: e[1] for e in ents}
    _, relocs = reloc_table(d, segs, ents)

    changed = False
    for arr_tag, sz_tag, label in ((25, 26, 'INIT'), (27, 28, 'FINI')):
        if arr_tag not in m:
            continue
        va, sz = m[arr_tag], m.get(sz_tag, 0)
        o = v2o(segs, va)
        if o is None or sz < 4:
            continue
        n = sz // 4
        vals = [struct.unpack_from('<I', d, o + i * 4)[0] for i in range(n)]
        nulls = [i for i in range(n)
                 if vals[i] == 0 and (o + i * 4) not in relocs]
        if not nulls:
            print('  %-4s array: %d entries, none NULL -> ok' % (label, n))
            continue
        print('  %-4s array: %d entries, NULL at %s' % (label, n, nulls))
        if nulls == list(range(nulls[0], n)):
            set_tag(ents, sz_tag, nulls[0] * 4)
            print('        -> DT_%s_ARRAYSZ %d -> %d' % (label, sz, nulls[0] * 4))
        else:
            keep = [v for i, v in enumerate(vals) if i not in nulls]
            for i, v in enumerate(keep):
                struct.pack_into('<I', d, o + i * 4, v)
            for i in range(len(keep), n):
                struct.pack_into('<I', d, o + i * 4, 0)
            for r_off, ent_off in relocs.items():
                if o <= r_off < o + n * 4:
                    slot = (r_off - o) // 4
                    new_slot = slot - sum(1 for x in nulls if x < slot)
                    struct.pack_into('<I', d, ent_off, o + new_slot * 4)
            set_tag(ents, sz_tag, len(keep) * 4)
            print('        -> shifted %d entries, DT_%s_ARRAYSZ %d -> %d'
                  % (len(keep), label, sz, len(keep) * 4))
        changed = True

    if changed and not dry:
        shutil.copyfile(path, path + '.preinit')
        open(path, 'wb').write(bytes(d))
        print('        patched %s' % path)
    return changed

if __name__ == '__main__':
    dry = '--dry' in sys.argv
    for p in sys.argv[1:]:
        if p.startswith('--'):
            continue
        print('==', p)
        if not patch(p, dry):
            print('  (nothing to do)')
PYEOF

