#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <execinfo.h>
#include <pthread.h>

static int (*real_lock)(pthread_mutex_t*);
static int (*real_unlock)(pthread_mutex_t*);
static int (*real_trylock)(pthread_mutex_t*);
static int (*real_init)(pthread_mutex_t*, const pthread_mutexattr_t*);
static int (*real_destroy)(pthread_mutex_t*);
static int inited;

static void probe_init(void) {
  if (inited) return;
  inited = 1;
  real_lock    = dlsym(RTLD_NEXT, "pthread_mutex_lock");
  real_unlock  = dlsym(RTLD_NEXT, "pthread_mutex_unlock");
  real_trylock = dlsym(RTLD_NEXT, "pthread_mutex_trylock");
  real_init    = dlsym(RTLD_NEXT, "pthread_mutex_init");
  real_destroy = dlsym(RTLD_NEXT, "pthread_mutex_destroy");
}
__attribute__((constructor)) static void probe_ctor(void) { probe_init(); }

/* glibc 32-bit struct __pthread_mutex_s */
struct gmutex {
  int lock; unsigned int count; int owner; unsigned int nusers;
  int kind; short spins; short elision; void* list[2];
};
/* bionic 32-bit struct __pthread_mutex_s */
struct bmutex {
  int lock; unsigned int owner; int type; int nusers; void* list[2];
};

static void dump(const char* tag, pthread_mutex_t* m) {
  struct gmutex* g = (struct gmutex*)m;
  struct bmutex* b = (struct bmutex*)m;
  fprintf(stderr, "\n[mutexprobe] %s mutex=%p\n", tag, (void*)m);
  fprintf(stderr, "[mutexprobe]   glibc: lock=%d count=%u owner=%d nusers=%u kind=%d\n",
          g->lock, g->count, g->owner, g->nusers, g->kind);
  fprintf(stderr, "[mutexprobe]   bionic: lock=%d owner=%u type=%d nusers=%d list=%p/%p\n",
          b->lock, b->owner, b->type, b->nusers, b->list[0], b->list[1]);
  void* bt[40];
  int n = backtrace(bt, 40);
  fprintf(stderr, "[mutexprobe]   --- backtrace ---\n");
  backtrace_symbols_fd(bt, n, 2);
  fflush(stderr);
}

int pthread_mutex_lock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-LOCK", m);
  return real_lock(m);
}

int pthread_mutex_trylock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-TRYLOCK", m);
  return real_trylock(m);
}

int pthread_mutex_unlock(pthread_mutex_t* m) {
  probe_init();
  return real_unlock(m);
}

int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* a) {
  probe_init();
  int r = real_init(m, a);
  struct gmutex* g = (struct gmutex*)m;
  fprintf(stderr, "[mutexprobe] INIT mutex=%p -> lock=%d count=%u owner=%d nusers=%u kind=%d attr=%p\n",
          (void*)m, g->lock, g->count, g->owner, g->nusers, g->kind, (const void*)a);
  if (a) {
    fprintf(stderr, "[mutexprobe]   attr bytes:");
    const unsigned char* p = (const unsigned char*)a;
    for (int i = 0; i < 32; i++) fprintf(stderr, " %02x", p[i]);
    fprintf(stderr, "\n");
  }
  fflush(stderr);
  return r;
}

int pthread_mutex_destroy(pthread_mutex_t* m) {
  probe_init();
  return real_destroy(m);
}
EOF

arm-linux-gnueabihf-gcc -O1 -fPIC -shared -o build/libmutexprobe.so src/mutex_probe.c -ldl
