    fprintf(stderr, "[mutexprobe]   %-10s ra=%p  (?)\n", tag, ra);
  }
}

static void dump(const char* tag, pthread_mutex_t* m, void* ra) {
  struct gmutex* g = (struct gmutex*)m;
  fprintf(stderr, "\n[mutexprobe] %s mutex=%p\n", tag, (void*)m);
  fprintf(stderr, "[mutexprobe]   words: lock=%d count=%u owner=%d nusers=%u kind=%d spins/el=%d/%d\n",
          g->lock, g->count, g->owner, g->nusers, g->kind, g->spins, g->elision);
  fprintf(stderr, "[mutexprobe]   raw:");
  const unsigned char* b = (const unsigned char*)m;
  for (int i = 0; i < 32; i++) fprintf(stderr, " %02x", b[i]);
  fprintf(stderr, "\n");
  show_caller("caller", ra);
  void* bt[40];
  int n = backtrace(bt, 40);
  if (n > 0) { fprintf(stderr, "[mutexprobe]   --- backtrace ---\n"); backtrace_symbols_fd(bt, n, 2); }
  fflush(stderr);
}

int pthread_mutex_lock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-LOCK", m, __builtin_return_address(0));
  return real_lock(m);
}

int pthread_mutex_trylock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-TRYLOCK", m, __builtin_return_address(0));
  return real_trylock(m);
}

int pthread_mutex_unlock(pthread_mutex_t* m) { probe_init(); return real_unlock(m); }

int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* a) {
  probe_init();
  int r = real_init(m, a);
  struct gmutex* g = (struct gmutex*)m;
  fprintf(stderr, "[mutexprobe] INIT mutex=%p kind=%d nusers=%u attr=%p caller=",
          (void*)m, g->kind, g->nusers, (const void*)a);
  { Dl_info di; void* ra = __builtin_return_address(0);
