    else fprintf(stderr, "%p\n", ra); }
  if (a) {
    fprintf(stderr, "[mutexprobe]   attr words:");
    const unsigned int* p = (const unsigned int*)a;
    for (int i = 0; i < 8; i++) fprintf(stderr, " %08x", p[i]);
    fprintf(stderr, "\n");
  }
  fflush(stderr);
  return r;
}

int pthread_mutex_destroy(pthread_mutex_t* m) { probe_init(); return real_destroy(m); }
