#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <execinfo.h>
#include <pthread.h>

static int (*real_lock)(pthread_mutex_t*);
static int (*real_unlock)(pthread_mutex_t*);
static int (*real_trylock)(pthread_mutex_t*);
static int (*real_init)(pthread_mutex_t*, const pthread_mutexattr_t*);
static int (*real_destroy)(pthread_mutex_t*);
static int inited;

static void probe_init(void) {
  if (inited) return;
  inited = 1;
  real_lock    = dlsym(RTLD_NEXT, "pthread_mutex_lock");
  real_unlock  = dlsym(RTLD_NEXT, "pthread_mutex_unlock");
  real_trylock = dlsym(RTLD_NEXT, "pthread_mutex_trylock");
  real_init    = dlsym(RTLD_NEXT, "pthread_mutex_init");
  real_destroy = dlsym(RTLD_NEXT, "pthread_mutex_destroy");
}
__attribute__((constructor)) static void probe_ctor(void) { probe_init(); }

struct gmutex {
  int lock; unsigned int count; int owner; unsigned int nusers;
  int kind; short spins; short elision; void* list[2];
};

static void show_caller(const char* tag, void* ra) {
  Dl_info di;
  if (ra && dladdr(ra, &di) && di.dli_fname) {
    fprintf(stderr, "[mutexprobe]   %-10s ra=%p  %s+0x%lx\n", tag, ra,
            di.dli_fname, (unsigned long)ra - (unsigned long)di.dli_fbase);
  } else {
    fprintf(stderr, "[mutexprobe]   %-10s ra=%p  (?)\n", tag, ra);
  }
}

static void dump(const char* tag, pthread_mutex_t* m, void* ra) {
  struct gmutex* g = (struct gmutex*)m;
  fprintf(stderr, "\n[mutexprobe] %s mutex=%p\n", tag, (void*)m);
  fprintf(stderr, "[mutexprobe]   words: lock=%d count=%u owner=%d nusers=%u kind=%d spins/el=%d/%d\n",
          g->lock, g->count, g->owner, g->nusers, g->kind, g->spins, g->elision);
  fprintf(stderr, "[mutexprobe]   raw:");
  const unsigned char* b = (const unsigned char*)m;
  for (int i = 0; i < 32; i++) fprintf(stderr, " %02x", b[i]);
  fprintf(stderr, "\n");
  show_caller("caller", ra);
  void* bt[40];
  int n = backtrace(bt, 40);
  if (n > 0) { fprintf(stderr, "[mutexprobe]   --- backtrace ---\n"); backtrace_symbols_fd(bt, n, 2); }
  fflush(stderr);
}

int pthread_mutex_lock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-LOCK", m, __builtin_return_address(0));
  return real_lock(m);
}

int pthread_mutex_trylock(pthread_mutex_t* m) {
  probe_init();
  struct gmutex* g = (struct gmutex*)m;
  if (g->kind == 0 && g->owner != 0) dump("BROKEN-TRYLOCK", m, __builtin_return_address(0));
  return real_trylock(m);
}

int pthread_mutex_unlock(pthread_mutex_t* m) { probe_init(); return real_unlock(m); }

int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* a) {
  probe_init();
  int r = real_init(m, a);
  struct gmutex* g = (struct gmutex*)m;
  fprintf(stderr, "[mutexprobe] INIT mutex=%p kind=%d nusers=%u attr=%p caller=",
          (void*)m, g->kind, g->nusers, (const void*)a);
  { Dl_info di; void* ra = __builtin_return_address(0);
    if (ra && dladdr(ra, &di) && di.dli_fname)
      fprintf(stderr, "%s+0x%lx\n", di.dli_fname, (unsigned long)ra - (unsigned long)di.dli_fbase);
    else fprintf(stderr, "%p\n", ra); }
  if (a) {
    fprintf(stderr, "[mutexprobe]   attr words:");
    const unsigned int* p = (const unsigned int*)a;
    for (int i = 0; i < 8; i++) fprintf(stderr, " %08x", p[i]);
    fprintf(stderr, "\n");
  }
  fflush(stderr);
  return r;
}

int pthread_mutex_destroy(pthread_mutex_t* m) { probe_init(); return real_destroy(m); }

=============== src/main.c ===============
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <unistd.h>
#include <signal.h>
#include <ucontext.h>

extern void* jni_stub_vm(void);

typedef int (*JNI_OnLoad_t)(void* vm, void* reserved);

static void* must_open(const char* path, int flags) {
  void* h = dlopen(path, flags);
  if (!h) fprintf(stderr, "dlopen(%s) FAILED: %s\n", path, dlerror());
  else fprintf(stderr, "dlopen(%s) ok -> %p\n", path, h);
  return h;
}

static void report(const char* what, void* addr) {
  Dl_info info;
  if (addr && dladdr(addr, &info) && info.dli_fname) {
    unsigned long off = (unsigned long)addr - (unsigned long)info.dli_fbase;
    fprintf(stderr, "  %-3s %p = %s+0x%lx", what, addr, info.dli_fname, off);
    if (info.dli_sname) fprintf(stderr, " (near %s)", info.dli_sname);
    fprintf(stderr, "\n");
  } else {
    fprintf(stderr, "  %-3s %p (not in any loaded object)\n", what, addr);
  }
}

static void on_segv(int sig, siginfo_t* si, void* uc_) {
  ucontext_t* uc = (ucontext_t*)uc_;
  fprintf(stderr, "\n=== SIGNAL %d, fault addr %p ===\n", sig, si->si_addr);
  report("pc", (void*)uc->uc_mcontext.arm_pc);
  report("lr", (void*)uc->uc_mcontext.arm_lr);
  report("sp", (void*)uc->uc_mcontext.arm_sp);
  fprintf(stderr, "=== end ===\n");
  _exit(139);
}

static void install_handler(void) {
  struct sigaction sa;
  memset(&sa, 0, sizeof(sa));
  sa.sa_sigaction = on_segv;
  sa.sa_flags = SA_SIGINFO;
  sigaction(SIGSEGV, &sa, NULL);
  sigaction(SIGBUS, &sa, NULL);
  sigaction(SIGILL, &sa, NULL);
  sigaction(SIGABRT, &sa, NULL);
}

int main(int argc, char** argv) {
  const char* dir = (argc > 1) ? argv[1] : ".";
  if (chdir(dir) != 0) { fprintf(stderr, "chdir(%s) failed\n", dir); return 1; }
  fprintf(stderr, "cwd = %s\n", dir);

  install_handler();

  void* vm = jni_stub_vm();
  fprintf(stderr, "stub JavaVM = %p\n", vm);

  must_open("./libbioniccompat.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./libandroid.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./liblog.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./libmain.so", RTLD_NOW | RTLD_GLOBAL);

  void* unity = must_open("./libunity.so", RTLD_NOW | RTLD_GLOBAL);
  if (!unity) { fprintf(stderr, "libunity load failed - stopping\n"); return 2; }

  void* il2cpp = must_open("./libil2cpp.so", RTLD_NOW | RTLD_GLOBAL);
  if (!il2cpp) fprintf(stderr, "  (continuing - Unity may load it itself)\n");

  JNI_OnLoad_t onload = (JNI_OnLoad_t)dlsym(unity, "JNI_OnLoad");
  if (!onload) onload = (JNI_OnLoad_t)dlsym(RTLD_DEFAULT, "JNI_OnLoad");
  if (!onload) { fprintf(stderr, "JNI_OnLoad not found\n"); return 3; }
  report("JNI_OnLoad", (void*)onload);

  fprintf(stderr, "calling JNI_OnLoad(%p, 0x00010006)\n", vm);
  int ver = onload(vm, (void*)0x00010006);
  fprintf(stderr, "JNI_OnLoad returned %d (0x%X)\n", ver, ver);
  return 0;
}

