static void wlog(const char* fmt, ...) {
  char buf[640];
  va_list ap; va_start(ap, fmt);
  int n = vsnprintf(buf, sizeof buf, fmt, ap);
  va_end(ap);
  if (n > 0) { if (n > 600) n = 600; fwrite(buf, 1, n, stderr); fflush(stderr); }
}

static void where(char* out, size_t n, void* p) {
  Dl_info di;
  if (p && dladdr(p, &di) && di.dli_fname) {
    const char* b = strrchr(di.dli_fname, '/'); b = b ? b + 1 : di.dli_fname;
