static void hist_add(void* m, int kind, int attrkind) {
  for (int i = 0; i < nhist; i++) if (hist[i].m == m) { hist[i].kind = kind; hist[i].attrkind = attrkind; hist[i].seq = ++seq; return; }
  if (nhist < NH) { hist[nhist].m = m; hist[nhist].kind = kind; hist[nhist].attrkind = attrkind; hist[nhist].seq = ++seq; nhist++; }
}
static void hist_find(void* m, int* kind, int* attrkind, unsigned* s) {
  for (int i = 0; i < nhist; i++) if (hist[i].m == m) { *kind = hist[i].kind; *attrkind = hist[i].attrkind; *s = hist[i].seq; return; }
