/* ------------------------------------------------------------------ */
/* shadow pools                                                        */
/* ------------------------------------------------------------------ */
#define POOL 512
#define HSIZE 1024

typedef struct { void* key; int slot; } HEnt;

static HEnt mhtab[HSIZE];   /* pthread_mutex_t */
static HEnt chtab[HSIZE];   /* pthread_cond_t  */
static HEnt shtab[HSIZE];   /* sem_t           */
static HEnt tatab[HSIZE];   /* pthread_attr_t  */

static pthread_mutex_t mpool[POOL];
static int mkind[POOL];
static unsigned char mused[POOL];
static pthread_cond_t cpool[POOL];
static unsigned char cused[POOL];
static sem_t spool[POOL];
static unsigned char sused[POOL];

typedef struct {
  size_t stacksize;
  int detach;
  int policy;
  struct sched_param param;
  int inited;
} ThrAttr;
static ThrAttr tpool[POOL];
static unsigned char tused[POOL];

/* guards the tables; only ever taken for a few instructions */
static pthread_mutex_t tab_lock = PTHREAD_MUTEX_INITIALIZER;

static unsigned hashp(const void* p) {
  unsigned long x = (unsigned long)p >> 4;
  x *= 2654435761UL;
  return (unsigned)(x & (HSIZE - 1));
}

static int lock_tab(void)   { return r_mutex_lock(&tab_lock); }
static void unlock_tab(void) { r_mutex_unlock(&tab_lock); }

/* generic table probe; *create != 0 allocates a pool slot */
static int probe(HEnt* tab, unsigned char* used, int poolsize,
                 void* key, int kind, int create, void* pool, size_t elemsize) {
  unsigned h = hashp(key);
  for (unsigned i = 0; i < HSIZE; i++) {
    HEnt* e = &tab[(h + i) & (HSIZE - 1)];
    if (e->key == key) return e->slot;
    if (e->key == NULL) {
      if (!create) return -1;
      int s = -1;
      for (int j = 0; j < poolsize; j++) if (!used[j]) { s = j; break; }
      if (s < 0) return -1;
      used[s] = 1;
      if (pool) {
        if (kind == 0) {                       /* pthread_cond_t */
          pthread_condattr_t ga;
          r_condattr_init(&ga);
          r_cond_init((pthread_cond_t*)pool + s, &ga);
          r_condattr_destroy(&ga);
        } else if (kind == 1) {                /* sem_t */
          r_sem_init((sem_t*)pool + s, 0, 0);
        } else {                               /* pthread_mutex_t */
          pthread_mutexattr_t ga;
          r_mutexattr_init(&ga);
          r_mutexattr_settype(&ga, kind);
          r_mutex_init((pthread_mutex_t*)pool + s, &ga);
          r_mutexattr_destroy(&ga);
        }
      }
      e->key = key;
      e->slot = s;
      return s;
    }
  }
  return -1;
}

static int mutex_slot(void* key, int kind, int create) {
  return probe(mhtab, mused, POOL, key, kind, create, mpool, sizeof(pthread_mutex_t));
}
static int cond_slot(void* key, int create) {
  return probe(chtab, cused, POOL, key, 0, create, cpool, sizeof(pthread_cond_t));
}
static int sem_slot(void* key, int create) {
  return probe(shtab, sused, POOL, key, 1, create, spool, sizeof(sem_t));
}

static void drop_slot(HEnt* tab, unsigned char* used, void* key) {
  unsigned h = hashp(key);
  for (unsigned i = 0; i < HSIZE; i++) {
    HEnt* e = &tab[(h + i) & (HSIZE - 1)];
    if (e->key == key) {
      e->key = NULL;
      e->slot = -1;
      return;
    }
    if (e->key == NULL) return;
  }
}

/* ------------------------------------------------------------------ */
/* pthread_mutex_t                                                     */
/* ------------------------------------------------------------------ */
int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* attr) {
  resolve_all();
  int kind = PTHREAD_MUTEX_RECURSIVE;         /* safe default */
  if (attr) kind = *(const int*)attr & 3;     /* bionic keeps the type in the low bits */
  lock_tab();
  int s = mutex_slot((void*)m, kind, 1);
  unlock_tab();
  if (s < 0) return ENOMEM;
  mkind[s] = kind;
  return 0;
}

int pthread_mutex_destroy(pthread_mutex_t* m) {
  resolve_all();
  lock_tab();
  int s = mutex_slot((void*)m, 0, 0);
  if (s >= 0) {
    r_mutex_destroy(&mpool[s]);
    mused[s] = 0;
    drop_slot(mhtab, mused, (void*)m);
  }
  unlock_tab();
  return 0;
}

int pthread_mutex_lock(pthread_mutex_t* m) {
  resolve_all();
  lock_tab();
  int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  unlock_tab();
  if (s < 0) return ENOMEM;
  return r_mutex_lock(&mpool[s]);
}

int pthread_mutex_trylock(pthread_mutex_t* m) {
  resolve_all();
  lock_tab();
  int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  unlock_tab();
  if (s < 0) return ENOMEM;
  return r_mutex_trylock(&mpool[s]);
}

int pthread_mutex_unlock(pthread_mutex_t* m) {
  resolve_all();
  lock_tab();
  int s = mutex_slot((void*)m, 0, 0);
  unlock_tab();
  if (s < 0) return EINVAL;
  return r_mutex_unlock(&mpool[s]);
}

/* ------------------------------------------------------------------ */
/* pthread_mutexattr_t  (bionic: 4 bytes, type in the low bits)        */
/* ------------------------------------------------------------------ */
int pthread_mutexattr_init(pthread_mutexattr_t* a) {
  resolve_all();
  memset(a, 0, 4);          /* exactly bionic's size - never touch more */
