    static void* libc;
    if (!libc) libc = dlopen("libc.so.6", RTLD_LAZY | RTLD_NOLOAD);
    if (libc) p = dlsym(libc, name);
  }
  return p;
}

static int g_state;   /* 0 = unresolved, 1 = resolving, 2 = ready */

static void resolve_all(void) {
  int s = __atomic_load_n(&g_state, __ATOMIC_ACQUIRE);
  if (s == 2) return;
  if (__atomic_compare_exchange_n(&g_state, &s, 1, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
    r_mutex_init          = (f_mutex_init)lookup_sym("pthread_mutex_init");
    r_mutex_destroy       = (f_mutex_destroy)lookup_sym("pthread_mutex_destroy");
    r_mutex_lock          = (f_mutex_lock)lookup_sym("pthread_mutex_lock");
    r_mutex_trylock       = (f_mutex_trylock)lookup_sym("pthread_mutex_trylock");
    r_mutex_unlock        = (f_mutex_unlock)lookup_sym("pthread_mutex_unlock");
    r_mutexattr_init      = (f_mutexattr_init)lookup_sym("pthread_mutexattr_init");
    r_mutexattr_destroy   = (f_mutexattr_destroy)lookup_sym("pthread_mutexattr_destroy");
    r_mutexattr_settype   = (f_mutexattr_settype)lookup_sym("pthread_mutexattr_settype");
    r_mutexattr_gettype   = (f_mutexattr_gettype)lookup_sym("pthread_mutexattr_gettype");
    r_cond_init           = (f_cond_init)lookup_sym("pthread_cond_init");
    r_cond_destroy        = (f_cond_destroy)lookup_sym("pthread_cond_destroy");
    r_cond_wait           = (f_cond_wait)lookup_sym("pthread_cond_wait");
    r_cond_timedwait      = (f_cond_timedwait)lookup_sym("pthread_cond_timedwait");
    r_cond_signal         = (f_cond_signal)lookup_sym("pthread_cond_signal");
    r_cond_broadcast      = (f_cond_broadcast)lookup_sym("pthread_cond_broadcast");
    r_condattr_init       = (f_condattr_init)lookup_sym("pthread_condattr_init");
    r_condattr_destroy    = (f_condattr_destroy)lookup_sym("pthread_condattr_destroy");
    r_condattr_setclock   = (f_condattr_setclock)lookup_sym("pthread_condattr_setclock");
    r_sem_init            = (f_sem_init)lookup_sym("sem_init");
    r_sem_destroy         = (f_sem_destroy)lookup_sym("sem_destroy");
    r_sem_wait            = (f_sem_wait)lookup_sym("sem_wait");
    r_sem_trywait         = (f_sem_trywait)lookup_sym("sem_trywait");
    r_sem_timedwait       = (f_sem_timedwait)lookup_sym("sem_timedwait");
    r_sem_post            = (f_sem_post)lookup_sym("sem_post");
    r_sem_getvalue        = (f_sem_getvalue)lookup_sym("sem_getvalue");
    r_attr_init           = (f_attr_init)lookup_sym("pthread_attr_init");
    r_attr_destroy        = (f_attr_destroy)lookup_sym("pthread_attr_destroy");
    r_attr_setstacksize   = (f_attr_setstacksize)lookup_sym("pthread_attr_setstacksize");
    r_attr_getstacksize   = (f_attr_getstacksize)lookup_sym("pthread_attr_getstacksize");
    r_attr_setdetachstate = (f_attr_setdetachstate)lookup_sym("pthread_attr_setdetachstate");
    r_attr_getdetachstate = (f_attr_getdetachstate)lookup_sym("pthread_attr_getdetachstate");
    r_attr_setschedparam  = (f_attr_setschedparam)lookup_sym("pthread_attr_setschedparam");
    r_attr_getschedparam  = (f_attr_getschedparam)lookup_sym("pthread_attr_getschedparam");
    r_attr_setschedpolicy = (f_attr_setschedpolicy)lookup_sym("pthread_attr_setschedpolicy");
    r_attr_getschedpolicy = (f_attr_getschedpolicy)lookup_sym("pthread_attr_getschedpolicy");
    r_attr_getstack       = (f_attr_getstack)lookup_sym("pthread_attr_getstack");
    r_thr_create          = (f_thr_create)lookup_sym("pthread_create");
    r_getattr_np          = (f_getattr_np)lookup_sym("pthread_getattr_np");
    __atomic_store_n(&g_state, 2, __ATOMIC_RELEASE);
  } else {
    while (__atomic_load_n(&g_state, __ATOMIC_ACQUIRE) != 2) sched_yield();
  }
}

/* ------------------------------------------------------------------ */
/* shadow pools and key -> slot tables                                 */
/* ------------------------------------------------------------------ */
#define HSIZE 2048
#define POOL  1024

typedef struct { void* key; int val; } Ent;

static Ent T_mutex[HSIZE];
static Ent T_cond[HSIZE];
static Ent T_sem[HSIZE];
static Ent T_attr[HSIZE];
static Ent T_mattr[HSIZE];   /* value = mutex kind 0..3            */
static Ent T_cattr[HSIZE];   /* value = clock id                   */

static pthread_mutex_t mpool[POOL];
static unsigned char   mused[POOL];
static int             mkind[POOL];

static pthread_cond_t  cpool[POOL];
static unsigned char   cused[POOL];
static int             cclock[POOL];

static sem_t           spool[POOL];
static unsigned char   sused[POOL];

typedef struct {
  size_t stacksize;
  void*  stackaddr;
  int    detach;
  int    policy;
  int    guardsize;
  struct sched_param param;
} ThrAttr;
static ThrAttr    tpool[POOL];
static unsigned char tused[POOL];

/* guards the tables; only taken for a few instructions */
static pthread_mutex_t tab_lock = PTHREAD_MUTEX_INITIALIZER;

static unsigned hsh(const void* p) {
  unsigned long x = (unsigned long)p >> 3;
  x *= 2654435761UL;
  x ^= x >> 13;
  return (unsigned)(x & (HSIZE - 1));
}

/* lock free read: entries are only inserted/removed rarely and a torn
 * pointer read is not possible on aligned 32 bit words. */
static int tfind(const Ent* t, const void* k) {
  unsigned h = hsh(k);
  for (unsigned i = 0; i < HSIZE; i++) {
    const Ent* e = &t[(h + i) & (HSIZE - 1)];
    if (e->key == k) return e->val;
    if (e->key == NULL) return -1;
  }
  return -1;
}

/* caller holds tab_lock */
static void tput(Ent* t, void* k, int val) {
  unsigned h = hsh(k);
  for (unsigned i = 0; i < HSIZE; i++) {
    Ent* e = &t[(h + i) & (HSIZE - 1)];
    if (e->key == k) { e->val = val; return; }
    if (e->key == NULL) { e->key = k; e->val = val; return; }
  }
}

/* caller holds tab_lock */
static void tdrop(Ent* t, const void* k) {
  unsigned h = hsh(k);
  for (unsigned i = 0; i < HSIZE; i++) {
    Ent* e = &t[(h + i) & (HSIZE - 1)];
    if (e->key == k) { e->key = NULL; e->val = -1; return; }
    if (e->key == NULL) return;
  }
}

static void lock_tab(void)   { r_mutex_lock(&tab_lock); }
static void unlock_tab(void) { r_mutex_unlock(&tab_lock); }

/* ------------------------------------------------------------------ */
/* pthread_mutex_t                                                      */
/* ------------------------------------------------------------------ */
static int mutex_slot(void* key, int kind, int create) {
  int s = tfind(T_mutex, key);
  if (s >= 0) return s;
  if (!create) return -1;
  lock_tab();
  s = tfind(T_mutex, key);
  if (s < 0) {
    for (int i = 0; i < POOL; i++) if (!mused[i]) { s = i; break; }
    if (s >= 0) {
      mused[s] = 1;
      mkind[s] = kind;
      pthread_mutexattr_t ga;
      r_mutexattr_init(&ga);
      r_mutexattr_settype(&ga, kind);
      r_mutex_init(&mpool[s], &ga);
      r_mutexattr_destroy(&ga);
      tput(T_mutex, key, s);
    }
  }
  unlock_tab();
  return s;
}

int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* attr) {
  resolve_all();
  int kind = PTHREAD_MUTEX_NORMAL;
  if (attr) {
    int k = tfind(T_mattr, attr);
    if (k >= 0) kind = k;
  }
  int s = mutex_slot((void*)m, kind, 1);
  return s < 0 ? ENOMEM : 0;
}

int pthread_mutex_destroy(pthread_mutex_t* m) {
  resolve_all();
  lock_tab();
  int s = tfind(T_mutex, (void*)m);
  if (s >= 0) {
    r_mutex_destroy(&mpool[s]);
    mused[s] = 0;
    tdrop(T_mutex, (void*)m);
  }
  unlock_tab();
  return 0;
}

int pthread_mutex_lock(pthread_mutex_t* m) {
  resolve_all();
  int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  if (s < 0) return ENOMEM;
  return r_mutex_lock(&mpool[s]);
}

int pthread_mutex_trylock(pthread_mutex_t* m) {
  resolve_all();
  int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  if (s < 0) return ENOMEM;
  return r_mutex_trylock(&mpool[s]);
}

int pthread_mutex_unlock(pthread_mutex_t* m) {
  resolve_all();
  int s = tfind(T_mutex, (void*)m);
  if (s < 0) return EINVAL;
  return r_mutex_unlock(&mpool[s]);
}

/* ------------------------------------------------------------------ */
/* pthread_mutexattr_t  (bionic: 4 byte int, type in the low 2 bits)   */
/* ------------------------------------------------------------------ */
int pthread_mutexattr_init(pthread_mutexattr_t* a) {
  resolve_all();
  lock_tab();
  int s = tfind(T_mattr, (void*)a);
  if (s < 0) {
    for (int i = 0; i < HSIZE; i++) { /* placeholder to keep pool logic uniform */ (void)i; break; }
    tput(T_mattr, (void*)a, PTHREAD_MUTEX_NORMAL);
  }
  unlock_tab();
  return 0;
}

int pthread_mutexattr_destroy(pthread_mutexattr_t* a) {
  resolve_all();
  lock_tab();
  tdrop(T_mattr, (void*)a);
  unlock_tab();
  return 0;
}

int pthread_mutexattr_settype(pthread_mutexattr_t* a, int type) {
  resolve_all();
  if (type < 0 || type > 3) return EINVAL;
  lock_tab();
  tput(T_mattr, (void*)a, type);
  unlock_tab();
  return 0;
}

int pthread_mutexattr_gettype(const pthread_mutexattr_t* a, int* type) {
  resolve_all();
  int k = tfind(T_mattr, (void*)a);
  *type = (k >= 0) ? k : PTHREAD_MUTEX_NORMAL;
  return 0;
}

int pthread_mutexattr_setpshared(pthread_mutexattr_t* a, int p) { (void)a; (void)p; return 0; }
int pthread_mutexattr_getpshared(const pthread_mutexattr_t* a, int* p) { (void)a; *p = 0; return 0; }
int pthread_mutexattr_setrobust(pthread_mutexattr_t* a, int r) { (void)a; (void)r; return 0; }
int pthread_mutexattr_getrobust(const pthread_mutexattr_t* a, int* r) { (void)a; *r = 0; return 0; }
int pthread_mutexattr_setprotocol(pthread_mutexattr_t* a, int p) { (void)a; (void)p; return 0; }
int pthread_mutexattr_getprotocol(const pthread_mutexattr_t* a, int* p) { (void)a; *p = 0; return 0; }

/* ------------------------------------------------------------------ */
/* pthread_cond_t                                                       */
/* ------------------------------------------------------------------ */
static int cond_slot(void* key, int clock, int create) {
  int s = tfind(T_cond, key);
  if (s >= 0) return s;
  if (!create) return -1;
  lock_tab();
  s = tfind(T_cond, key);
  if (s < 0) {
    for (int i = 0; i < POOL; i++) if (!cused[i]) { s = i; break; }
    if (s >= 0) {
      cused[s] = 1;
      cclock[s] = clock;
      pthread_condattr_t ga;
      r_condattr_init(&ga);
      if (clock != CLOCK_REALTIME) r_condattr_setclock(&ga, clock);
      r_cond_init(&cpool[s], &ga);
      r_condattr_destroy(&ga);
      tput(T_cond, key, s);
    }
  }
  unlock_tab();
  return s;
}

int pthread_cond_init(pthread_cond_t* c, const pthread_condattr_t* attr) {
  resolve_all();
  int clock = CLOCK_REALTIME;
  if (attr) {
    int k = tfind(T_cattr, attr);
    if (k >= 0) clock = k;
  }
  int s = cond_slot((void*)c, clock, 1);
  return s < 0 ? ENOMEM : 0;
}

int pthread_cond_destroy(pthread_cond_t* c) {
  resolve_all();
  lock_tab();
  int s = tfind(T_cond, (void*)c);
  if (s >= 0) { r_cond_destroy(&cpool[s]); cused[s] = 0; tdrop(T_cond, (void*)c); }
  unlock_tab();
  return 0;
}

int pthread_cond_wait(pthread_cond_t* c, pthread_mutex_t* m) {
  resolve_all();
  int cs = cond_slot((void*)c, CLOCK_REALTIME, 1);
  int ms = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  if (cs < 0 || ms < 0) return EINVAL;
  return r_cond_wait(&cpool[cs], &mpool[ms]);
}

int pthread_cond_timedwait(pthread_cond_t* c, pthread_mutex_t* m,
                            const struct timespec* ts) {
  resolve_all();
  int cs = cond_slot((void*)c, CLOCK_REALTIME, 1);
  int ms = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
  if (cs < 0 || ms < 0) return EINVAL;
  return r_cond_timedwait(&cpool[cs], &mpool[ms], ts);
}

int pthread_cond_signal(pthread_cond_t* c) {
  resolve_all();
  int cs = cond_slot((void*)c, CLOCK_REALTIME, 1);
  if (cs < 0) return EINVAL;
  return r_cond_signal(&cpool[cs]);
}

int pthread_cond_broadcast(pthread_cond_t* c) {
  resolve_all();
  int cs = cond_slot((void*)c, CLOCK_REALTIME, 1);
  if (cs < 0) return EINVAL;
  return r_cond_broadcast(&cpool[cs]);
}

/* ------------------------------------------------------------------ */
/* pthread_condattr_t                                                   */
/* ------------------------------------------------------------------ */
int pthread_condattr_init(pthread_condattr_t* a) {
  resolve_all();
  lock_tab();
  tput(T_cattr, (void*)a, CLOCK_REALTIME);
  unlock_tab();
  return 0;
}
int pthread_condattr_destroy(pthread_condattr_t* a) {
  resolve_all();
  lock_tab();
  tdrop(T_cattr, (void*)a);
  unlock_tab();
  return 0;
}
int pthread_condattr_setclock(pthread_condattr_t* a, clockid_t clk) {
  resolve_all();
  lock_tab();
  tput(T_cattr, (void*)a, (int)clk);
  unlock_tab();
  return 0;
}
int pthread_condattr_getclock(const pthread_condattr_t* a, clockid_t* clk) {
  resolve_all();
  int k = tfind(T_cattr, (void*)a);
  *clk = (k >= 0) ? (clockid_t)k : CLOCK_REALTIME;
  return 0;
}
int pthread_condattr_setpshared(pthread_condattr_t* a, int p) { (void)a; (void)p; return 0; }
int pthread_condattr_getpshared(const pthread_condattr_t* a, int* p) { (void)a; *p = 0; return 0; }

/* ------------------------------------------------------------------ */
/* sem_t                                                                */
/* ------------------------------------------------------------------ */
static int sem_slot(void* key, int create) {
  int s = tfind(T_sem, key);
  if (s >= 0) return s;
  if (!create) return -1;
  lock_tab();
  s = tfind(T_sem, key);
  if (s < 0) {
    for (int i = 0; i < POOL; i++) if (!sused[i]) { s = i; break; }
    if (s >= 0) { sused[s] = 1; tput(T_sem, key, s); }
  }
  unlock_tab();
  return s;
}

int sem_init(sem_t* s, int pshared, unsigned value) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return ENOMEM;
  r_sem_destroy(&spool[slot]);
  return r_sem_init(&spool[slot], pshared, value);
}

int sem_destroy(sem_t* s) {
  resolve_all();
  lock_tab();
  int slot = tfind(T_sem, (void*)s);
  if (slot >= 0) { r_sem_destroy(&spool[slot]); sused[slot] = 0; tdrop(T_sem, (void*)s); }
  unlock_tab();
  return 0;
}

int sem_wait(sem_t* s) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return ENOMEM;
  return r_sem_wait(&spool[slot]);
}

int sem_trywait(sem_t* s) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return ENOMEM;
  return r_sem_trywait(&spool[slot]);
}

int sem_timedwait(sem_t* s, const struct timespec* ts) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return ENOMEM;
  return r_sem_timedwait(&spool[slot], ts);
}

int sem_post(sem_t* s) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return ENOMEM;
  return r_sem_post(&spool[slot]);
}

int sem_getvalue(sem_t* s, int* val) {
  resolve_all();
  int slot = sem_slot((void*)s, 1);
  if (slot < 0) return EINVAL;
  return r_sem_getvalue(&spool[slot], val);
}

/* ------------------------------------------------------------------ */
/* pthread_attr_t / pthread_create                                     */
/* ------------------------------------------------------------------ */
static int attr_slot(void* key, int create) {
  int s = tfind(T_attr, key);
  if (s >= 0) return s;
  if (!create) return -1;
  lock_tab();
  s = tfind(T_attr, key);
  if (s < 0) {
    for (int i = 0; i < POOL; i++) if (!tused[i]) { s = i; break; }
    if (s >= 0) {
      tused[s] = 1;
      tpool[s].stacksize = B_DEFAULT_STACK;
      tpool[s].stackaddr = NULL;
      tpool[s].detach = PTHREAD_CREATE_JOINABLE;
      tpool[s].policy = SCHED_OTHER;
      tpool[s].guardsize = B_DEFAULT_GUARD;
      memset(&tpool[s].param, 0, sizeof tpool[s].param);
      tput(T_attr, key, s);
    }
  }
  unlock_tab();
  return s;
}

int pthread_attr_init(pthread_attr_t* a) {
  resolve_all();
  int s = attr_slot((void*)a, 1);
  return s < 0 ? ENOMEM : 0;
}

int pthread_attr_destroy(pthread_attr_t* a) {
  resolve_all();
  lock_tab();
  int s = tfind(T_attr, (void*)a);
  if (s >= 0) { tused[s] = 0; tdrop(T_attr, (void*)a); }
  unlock_tab();
  return 0;
}

int pthread_attr_setstacksize(pthread_attr_t* a, size_t size) {
  resolve_all();
  if (size < B_MIN_STACK) return EINVAL;
  lock_tab();
  int s = attr_slot((void*)a, 1);
  if (s >= 0) tpool[s].stacksize = size;
  unlock_tab();
  return 0;
}

int pthread_attr_getstacksize(const pthread_attr_t* a, size_t* size) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  *size = (s >= 0) ? tpool[s].stacksize : B_DEFAULT_STACK;
  return 0;
}

int pthread_attr_setdetachstate(pthread_attr_t* a, int state) {
  resolve_all();
  if (state != PTHREAD_CREATE_JOINABLE && state != PTHREAD_CREATE_DETACHED) return EINVAL;
  lock_tab();
  int s = attr_slot((void*)a, 1);
  if (s >= 0) tpool[s].detach = state;
  unlock_tab();
  return 0;
}

int pthread_attr_getdetachstate(const pthread_attr_t* a, int* state) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  *state = (s >= 0) ? tpool[s].detach : PTHREAD_CREATE_JOINABLE;
  return 0;
}

int pthread_attr_setschedparam(pthread_attr_t* a, const struct sched_param* p) {
  resolve_all();
  lock_tab();
  int s = attr_slot((void*)a, 1);
  if (s >= 0 && p) tpool[s].param = *p;
  unlock_tab();
  return 0;
}

int pthread_attr_getschedparam(const pthread_attr_t* a, struct sched_param* p) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  if (p) { if (s >= 0) *p = tpool[s].param; else memset(p, 0, sizeof *p); }
  return 0;
}

int pthread_attr_setschedpolicy(pthread_attr_t* a, int policy) {
  resolve_all();
  lock_tab();
  int s = attr_slot((void*)a, 1);
  if (s >= 0) tpool[s].policy = policy;
  unlock_tab();
  return 0;
}

int pthread_attr_getschedpolicy(const pthread_attr_t* a, int* policy) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  *policy = (s >= 0) ? tpool[s].policy : SCHED_OTHER;
  return 0;
}

int pthread_attr_setguardsize(pthread_attr_t* a, size_t size) {
  resolve_all();
  lock_tab();
  int s = attr_slot((void*)a, 1);
  if (s >= 0) tpool[s].guardsize = (int)size;
  unlock_tab();
  return 0;
}
int pthread_attr_getguardsize(const pthread_attr_t* a, size_t* size) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  *size = (s >= 0) ? (size_t)tpool[s].guardsize : B_DEFAULT_GUARD;
  return 0;
}
int pthread_attr_setinheritsched(pthread_attr_t* a, int inherit) { (void)a; (void)inherit; return 0; }
int pthread_attr_getinheritsched(const pthread_attr_t* a, int* inherit) { (void)a; *inherit = 0; return 0; }
int pthread_attr_setstack(pthread_attr_t* a, void* stack, size_t size) {
  (void)a; (void)stack; (void)size; return ENOTSUP;
}
int pthread_attr_getstack(const pthread_attr_t* a, void** stack, size_t* size) {
  resolve_all();
  int s = tfind(T_attr, (void*)a);
  if (stack) *stack = (s >= 0) ? tpool[s].stackaddr : NULL;
  if (size)  *size  = (s >= 0) ? tpool[s].stacksize : B_DEFAULT_STACK;
  return 0;
}

/* bionic's pthread_attr_getstack returns attr->stack_base / attr->stack_size */
int pthread_attr_getstack_np(const pthread_attr_t* a, void** stack, size_t* size) {
  return pthread_attr_getstack(a, stack, size);
}

int pthread_create(pthread_t* th, const pthread_attr_t* attr,
                    void* (*fn)(void*), void* arg) {
  resolve_all();
  pthread_attr_t ga;
  r_attr_init(&ga);
  if (attr) {
    lock_tab();
    int s = tfind(T_attr, (void*)attr);
    if (s >= 0) {
      size_t ss = tpool[s].stacksize;
      if (ss) {
        if (ss < 65536) ss = 65536;               /* glibc PTHREAD_STACK_MIN */
        r_attr_setstacksize(&ga, ss);
      }
      r_attr_setdetachstate(&ga, tpool[s].detach);
      if (tpool[s].policy != SCHED_OTHER) {
        r_attr_setschedpolicy(&ga, tpool[s].policy);
        r_attr_setschedparam(&ga, &tpool[s].param);
      }
    }
    unlock_tab();
  }
  int r = r_thr_create(th, &ga, fn, arg);
  r_attr_destroy(&ga);
  return r;
}

/* ------------------------------------------------------------------ */
/* pthread_getattr_np - bionic layout                                   */
/* ------------------------------------------------------------------ */
int pthread_getattr_np(pthread_t t, pthread_attr_t* attr) {
  resolve_all();
  void* base = NULL;
  size_t sz = 0;
  if (r_getattr_np) {
    pthread_attr_t local;
    if (r_getattr_np(t, &local) == 0 && r_attr_getstack)
      r_attr_getstack(&local, &base, &sz);
  }
