=============== src/main.c ===============
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <unistd.h>
#include <signal.h>
#include <ucontext.h>

extern void* jni_stub_vm(void);

typedef int (*JNI_OnLoad_t)(void* vm, void* reserved);

static void* must_open(const char* path, int flags) {
  void* h = dlopen(path, flags);
  if (!h) fprintf(stderr, "dlopen(%s) FAILED: %s\n", path, dlerror());
  else fprintf(stderr, "dlopen(%s) ok -> %p\n", path, h);
  return h;
}

static void report(const char* what, void* addr) {
  Dl_info info;
  if (addr && dladdr(addr, &info) && info.dli_fname) {
    unsigned long off = (unsigned long)addr - (unsigned long)info.dli_fbase;
    fprintf(stderr, "  %-3s %p = %s+0x%lx", what, addr, info.dli_fname, off);
    if (info.dli_sname) fprintf(stderr, " (near %s)", info.dli_sname);
    fprintf(stderr, "\n");
  } else {
    fprintf(stderr, "  %-3s %p (not in any loaded object)\n", what, addr);
  }
}

static void on_segv(int sig, siginfo_t* si, void* uc_) {
  ucontext_t* uc = (ucontext_t*)uc_;
  fprintf(stderr, "\n=== SIGNAL %d, fault addr %p ===\n", sig, si->si_addr);
  report("pc", (void*)uc->uc_mcontext.arm_pc);
  report("lr", (void*)uc->uc_mcontext.arm_lr);
  report("sp", (void*)uc->uc_mcontext.arm_sp);
  fprintf(stderr, "=== end ===\n");
  _exit(139);
}

static void install_handler(void) {
  struct sigaction sa;
  memset(&sa, 0, sizeof(sa));
  sa.sa_sigaction = on_segv;
  sa.sa_flags = SA_SIGINFO;
  sigaction(SIGSEGV, &sa, NULL);
  sigaction(SIGBUS, &sa, NULL);
  sigaction(SIGILL, &sa, NULL);
  sigaction(SIGABRT, &sa, NULL);
}

int main(int argc, char** argv) {
  const char* dir = (argc > 1) ? argv[1] : ".";
  if (chdir(dir) != 0) { fprintf(stderr, "chdir(%s) failed\n", dir); return 1; }
  fprintf(stderr, "cwd = %s\n", dir);

  install_handler();

  void* vm = jni_stub_vm();
  fprintf(stderr, "stub JavaVM = %p\n", vm);

  must_open("./libbioniccompat.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./libandroid.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./liblog.so", RTLD_NOW | RTLD_GLOBAL);
  must_open("./libmain.so", RTLD_NOW | RTLD_GLOBAL);

  void* unity = must_open("./libunity.so", RTLD_NOW | RTLD_GLOBAL);
  if (!unity) { fprintf(stderr, "libunity load failed - stopping\n"); return 2; }

  void* il2cpp = must_open("./libil2cpp.so", RTLD_NOW | RTLD_GLOBAL);
  if (!il2cpp) fprintf(stderr, "  (continuing - Unity may load it itself)\n");

  JNI_OnLoad_t onload = (JNI_OnLoad_t)dlsym(unity, "JNI_OnLoad");
