145:     if (!libc) libc = dlopen("libc.so.6", RTLD_LAZY | RTLD_NOLOAD);
146:     if (libc) p = dlsym(libc, name);
147:   }
148:   return p;
149: }
150: 
151: static int g_state;   /* 0 = unresolved, 1 = resolving, 2 = ready */
152: 
153: static void resolve_all(void) {
154:   int s = __atomic_load_n(&g_state, __ATOMIC_ACQUIRE);
155:   if (s == 2) return;
156:   if (__atomic_compare_exchange_n(&g_state, &s, 1, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
157:     r_mutex_init          = (f_mutex_init)lookup_sym("pthread_mutex_init");
158:     r_mutex_destroy       = (f_mutex_destroy)lookup_sym("pthread_mutex_destroy");
159:     r_mutex_lock          = (f_mutex_lock)lookup_sym("pthread_mutex_lock");
160:     r_mutex_trylock       = (f_mutex_trylock)lookup_sym("pthread_mutex_trylock");
161:     r_mutex_unlock        = (f_mutex_unlock)lookup_sym("pthread_mutex_unlock");
162:     r_mutexattr_init      = (f_mutexattr_init)lookup_sym("pthread_mutexattr_init");
163:     r_mutexattr_destroy   = (f_mutexattr_destroy)lookup_sym("pthread_mutexattr_destroy");
164:     r_mutexattr_settype   = (f_mutexattr_settype)lookup_sym("pthread_mutexattr_settype");
165:     r_mutexattr_gettype   = (f_mutexattr_gettype)lookup_sym("pthread_mutexattr_gettype");
166:     r_cond_init           = (f_cond_init)lookup_sym("pthread_cond_init");
167:     r_cond_destroy        = (f_cond_destroy)lookup_sym("pthread_cond_destroy");
168:     r_cond_wait           = (f_cond_wait)lookup_sym("pthread_cond_wait");
