170:     r_cond_signal         = (f_cond_signal)lookup_sym("pthread_cond_signal");
171:     r_cond_broadcast      = (f_cond_broadcast)lookup_sym("pthread_cond_broadcast");
172:     r_condattr_init       = (f_condattr_init)lookup_sym("pthread_condattr_init");
