181:     r_sem_getvalue        = (f_sem_getvalue)lookup_sym("sem_getvalue");
182:     r_attr_init           = (f_attr_init)lookup_sym("pthread_attr_init");
183:     r_attr_destroy        = (f_attr_destroy)lookup_sym("pthread_attr_destroy");
184:     r_attr_setstacksize   = (f_attr_setstacksize)lookup_sym("pthread_attr_setstacksize");
185:     r_attr_getstacksize   = (f_attr_getstacksize)lookup_sym("pthread_attr_getstacksize");
186:     r_attr_setdetachstate = (f_attr_setdetachstate)lookup_sym("pthread_attr_setdetachstate");
187:     r_attr_getdetachstate = (f_attr_getdetachstate)lookup_sym("pthread_attr_getdetachstate");
188:     r_attr_setschedparam  = (f_attr_setschedparam)lookup_sym("pthread_attr_setschedparam");
189:     r_attr_getschedparam  = (f_attr_getschedparam)lookup_sym("pthread_attr_getschedparam");
190:     r_attr_setschedpolicy = (f_attr_setschedpolicy)lookup_sym("pthread_attr_setschedpolicy");
191:     r_attr_getschedpolicy = (f_attr_getschedpolicy)lookup_sym("pthread_attr_getschedpolicy");
