193:     r_thr_create          = (f_thr_create)lookup_sym("pthread_create");
194:     r_getattr_np          = (f_getattr_np)lookup_sym("pthread_getattr_np");
195:     __atomic_store_n(&g_state, 2, __ATOMIC_RELEASE);
196:   } else {
197:     while (__atomic_load_n(&g_state, __ATOMIC_ACQUIRE) != 2) sched_yield();
