201: /* ------------------------------------------------------------------ */
202: /* shadow pools and key -> slot tables                                 */
203: /* ------------------------------------------------------------------ */
204: #define HSIZE 2048
205: #define POOL  1024
206: 
207: typedef struct { void* key; int val; } Ent;
208: 
209: static Ent T_mutex[HSIZE];
210: static Ent T_cond[HSIZE];
211: static Ent T_sem[HSIZE];
212: static Ent T_attr[HSIZE];
213: static Ent T_mattr[HSIZE];   /* value = mutex kind 0..3            */
214: static Ent T_cattr[HSIZE];   /* value = clock id                   */
215: 
216: static pthread_mutex_t mpool[POOL];
217: static unsigned char   mused[POOL];
218: static int             mkind[POOL];
219: 
220: static pthread_cond_t  cpool[POOL];
221: static unsigned char   cused[POOL];
222: static int             cclock[POOL];
223: 
224: static sem_t           spool[POOL];
225: static unsigned char   sused[POOL];
226: 
227: typedef struct {
228:   size_t stacksize;
229:   void*  stackaddr;
230:   int    detach;
231:   int    policy;
232:   int    guardsize;
233:   struct sched_param param;
234: } ThrAttr;
235: static ThrAttr    tpool[POOL];
236: static unsigned char tused[POOL];
237: 
238: /* guards the tables; only taken for a few instructions */
239: static pthread_mutex_t tab_lock = PTHREAD_MUTEX_INITIALIZER;
240: 
241: static unsigned hsh(const void* p) {
242:   unsigned long x = (unsigned long)p >> 3;
243:   x *= 2654435761UL;
244:   x ^= x >> 13;
245:   return (unsigned)(x & (HSIZE - 1));
246: }
247: 
248: /* lock free read: entries are only inserted/removed rarely and a torn
249:  * pointer read is not possible on aligned 32 bit words. */
250: static int tfind(const Ent* t, const void* k) {
251:   unsigned h = hsh(k);
252:   for (unsigned i = 0; i < HSIZE; i++) {
253:     const Ent* e = &t[(h + i) & (HSIZE - 1)];
254:     if (e->key == k) return e->val;
255:     if (e->key == NULL) return -1;
256:   }
257:   return -1;
258: }
259: 
260: /* caller holds tab_lock */
261: static void tput(Ent* t, void* k, int val) {
262:   unsigned h = hsh(k);
263:   for (unsigned i = 0; i < HSIZE; i++) {
264:     Ent* e = &t[(h + i) & (HSIZE - 1)];
265:     if (e->key == k) { e->val = val; return; }
266:     if (e->key == NULL) { e->key = k; e->val = val; return; }
267:   }
268: }
269: 
270: /* caller holds tab_lock */
271: static void tdrop(Ent* t, const void* k) {
272:   unsigned h = hsh(k);
273:   for (unsigned i = 0; i < HSIZE; i++) {
274:     Ent* e = &t[(h + i) & (HSIZE - 1)];
275:     if (e->key == k) { e->key = NULL; e->val = -1; return; }
276:     if (e->key == NULL) return;
277:   }
278: }
279: 
280: static void lock_tab(void)   { r_mutex_lock(&tab_lock); }
281: static void unlock_tab(void) { r_mutex_unlock(&tab_lock); }
282: 
283: /* ------------------------------------------------------------------ */
284: /* pthread_mutex_t                                                      */
285: /* ------------------------------------------------------------------ */
286: /* caller holds tab_lock */
287: static int mutex_slot_locked(void* key, int kind, int create) {
288:   int s = tfind(T_mutex, key);
289:   if (s >= 0) return s;
290:   if (!create) return -1;
291:   for (int i = 0; i < POOL; i++) if (!mused[i]) { s = i; break; }
292:   if (s >= 0) {
293:     mused[s] = 1;
294:     mkind[s] = kind;
295:     pthread_mutexattr_t ga;
296:     r_mutexattr_init(&ga);
297:     r_mutexattr_settype(&ga, kind);
298:     r_mutex_init(&mpool[s], &ga);
299:     r_mutexattr_destroy(&ga);
300:     tput(T_mutex, key, s);
301:   }
302:   return s;
303: }
304: 
305: static int mutex_slot(void* key, int kind, int create) {
306:   int s = tfind(T_mutex, key);
307:   if (s >= 0) return s;
308:   if (!create) return -1;
309:   lock_tab();
310:   s = mutex_slot_locked(key, kind, 1);
311:   unlock_tab();
312:   return s;
313: }
314: 
315: int pthread_mutex_init(pthread_mutex_t* m, const pthread_mutexattr_t* attr) {
316:   resolve_all();
317:   int kind = PTHREAD_MUTEX_NORMAL;
318:   if (attr) {
319:     int k = tfind(T_mattr, attr);
320:     if (k >= 0) kind = k;
321:   }
322:   int s = mutex_slot((void*)m, kind, 1);
323:   return s < 0 ? ENOMEM : 0;
324: }
325: 
326: int pthread_mutex_destroy(pthread_mutex_t* m) {
327:   resolve_all();
328:   lock_tab();
329:   int s = tfind(T_mutex, (void*)m);
330:   if (s >= 0) {
331:     r_mutex_destroy(&mpool[s]);
332:     mused[s] = 0;
333:     tdrop(T_mutex, (void*)m);
334:   }
335:   unlock_tab();
336:   return 0;
337: }
338: 
339: int pthread_mutex_lock(pthread_mutex_t* m) {
340:   resolve_all();
341:   int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
342:   if (s < 0) return ENOMEM;
343:   return r_mutex_lock(&mpool[s]);
344: }
345: 
346: int pthread_mutex_trylock(pthread_mutex_t* m) {
347:   resolve_all();
348:   int s = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
349:   if (s < 0) return ENOMEM;
350:   return r_mutex_trylock(&mpool[s]);
351: }
352: 
353: int pthread_mutex_unlock(pthread_mutex_t* m) {
354:   resolve_all();
355:   int s = tfind(T_mutex, (void*)m);
356:   if (s < 0) return EINVAL;
357:   return r_mutex_unlock(&mpool[s]);
358: }
