403: /* pthread_cond_t                                                       */
404: /* ------------------------------------------------------------------ */
405: static int cond_slot_locked(void* key, int clock, int create) {
406:   int s = tfind(T_cond, key);
407:   if (s >= 0) return s;
408:   if (!create) return -1;
409:   for (int i = 0; i < POOL; i++) if (!cused[i]) { s = i; break; }
410:   if (s >= 0) {
411:     cused[s] = 1;
412:     cclock[s] = clock;
413:     pthread_condattr_t ga;
414:     r_condattr_init(&ga);
415:     if (clock != CLOCK_REALTIME) r_condattr_setclock(&ga, clock);
416:     r_cond_init(&cpool[s], &ga);
417:     r_condattr_destroy(&ga);
418:     tput(T_cond, key, s);
419:   }
420:   return s;
421: }
422: 
423: static int cond_slot(void* key, int clock, int create) {
424:   int s = tfind(T_cond, key);
425:   if (s >= 0) return s;
426:   if (!create) return -1;
427:   lock_tab();
428:   s = cond_slot_locked(key, clock, 1);
429:   unlock_tab();
430:   return s;
431: }
432: 
433: int pthread_cond_init(pthread_cond_t* c, const pthread_condattr_t* attr) {
434:   resolve_all();
435:   int clock = CLOCK_REALTIME;
436:   if (attr) {
437:     int k = tfind(T_cattr, attr);
438:     if (k >= 0) clock = k;
439:   }
440:   int s = cond_slot((void*)c, clock, 1);
441:   return s < 0 ? ENOMEM : 0;
442: }
443: 
444: int pthread_cond_destroy(pthread_cond_t* c) {
445:   resolve_all();
446:   lock_tab();
447:   int s = tfind(T_cond, (void*)c);
448:   if (s >= 0) { r_cond_destroy(&cpool[s]); cused[s] = 0; tdrop(T_cond, (void*)c); }
449:   unlock_tab();
450:   return 0;
451: }
