453: int pthread_cond_wait(pthread_cond_t* c, pthread_mutex_t* m) {
454:   resolve_all();
455:   int cs = cond_slot((void*)c, CLOCK_REALTIME, 1);
456:   int ms = mutex_slot((void*)m, PTHREAD_MUTEX_RECURSIVE, 1);
457:   if (cs < 0 || ms < 0) return EINVAL;
458:   return r_cond_wait(&cpool[cs], &mpool[ms]);
459: }
