597: static int attr_slot_locked(void* key, int create) {
598:   int s = tfind(T_attr, key);
599:   if (s >= 0) return s;
600:   if (!create) return -1;
601:   for (int i = 0; i < POOL; i++) if (!tused[i]) { s = i; break; }
602:   if (s >= 0) {
603:     tused[s] = 1;
604:     tpool[s].stacksize = B_DEFAULT_STACK;
605:     tpool[s].stackaddr = NULL;
606:     tpool[s].detach = PTHREAD_CREATE_JOINABLE;
607:     tpool[s].policy = SCHED_OTHER;
608:     tpool[s].guardsize = B_DEFAULT_GUARD;
609:     memset(&tpool[s].param, 0, sizeof tpool[s].param);
610:     tput(T_attr, key, s);
611:   }
612:   return s;
613: }
