static int tfind(const Ent* t, const void* k) {
  unsigned h = hsh(k);
  for (unsigned i = 0; i < HSIZE; i++) {
    const Ent* e = &t[(h + i) & (HSIZE - 1)];
    if (e->key == k) return e->val;
    if (e->key == NULL) return -1;   /* end of chain */
    /* tombstone -> keep probing */
  }
  return -1;
}

static void tput(Ent* t, void* k, int val) {
  unsigned h = hsh(k);
  Ent* first_tomb = NULL;
  for (unsigned i = 0; i < HSIZE; i++) {
    Ent* e = &t[(h + i) & (HSIZE - 1)];
    if (e->key == k) { e->val = val; return; }
    if (e->key == TOMB && !first_tomb) first_tomb = e;
    if (e->key == NULL) {
