/* stdio: translate bionic's __sF-derived FILE* to glibc's.            */
/* ------------------------------------------------------------------ */
#define HS_SF_STRIDE 84

static FILE* hs_to_glibc(FILE* f) {
    if (!f) return f;
    char* base = __sF;
    if (f == (FILE*)(base + 0 * HS_SF_STRIDE)) return stdin;
    if (f == (FILE*)(base + 1 * HS_SF_STRIDE)) return stdout;
    if (f == (FILE*)(base + 2 * HS_SF_STRIDE)) return stderr;
    return f;
}

int fclose(FILE* stream) {
    resolve_all();
    FILE* g = hs_to_glibc(stream);
    if (g == stdin || g == stdout || g == stderr) return 0;
    return r_fclose ? r_fclose(g) : 0;
}

